class CommonFixedIncomeInterestActivityV2(ValidateBaseModel):
    """
    Fixed income interest fields (INT/FI). Variants from the same activity type:

    - Coupon: `interest_type` is `coupon`. Includes `rate` (no `price` / `accrued_interest_rate`). No `order_id`.
    - Accrued interest on call: `interest_type` is `accrued`. Includes `price` and `accrued_interest_rate` (no `rate`). No `order_id`.
    - Trade accrued: `interest_type` is `accrued`. Includes `order_id` so the interest NTA can be linked to the fill. `parent_id` is set when a parent trade `ref_id` is available.
    """

    accrued_interest_rate: Optional[StrictStr] = Field(
        default=None,
        description="Accrued interest rate (present for accrued-interest-on-call variants)",
    )
    cash_payout: StrictStr = Field(
        description="The cash payout for this interest activity"
    )
    cusip: StrictStr = Field(
        description="The CUSIP of the security involved with the activity"
    )
    entitled_qty: StrictStr = Field(
        description="The entitled quantity (principal / face amount)",
        json_schema_extra={"examples": ["1000"]},
    )
    interest_type: FixedIncomeInterestType
    isin: Optional[StrictStr] = Field(
        default=None, description="The ISIN of the security involved with the activity"
    )
    order_id: Optional[UUID] = Field(
        default=None,
        description="The order that generated this accrued interest. Present for trade-accrued INT/FI.",
        json_schema_extra={"examples": ["257bf308-a6b7-4777-8cf6-00dc441dc4d3"]},
    )
    parent_id: Optional[UUID] = Field(
        default=None,
        description="The ref_id of the parent trade this interest is attached to. Present for trade-accrued INT/FI when a parent trade `ref_id` is available.",
        json_schema_extra={"examples": ["46aecae1-4629-4bcf-b441-0d8c847a1787"]},
    )
    payment_date: Optional[date] = Field(default=None, description="The payment date")
    price: Optional[StrictStr] = Field(
        default=None,
        description="Call price used for accrued-interest-on-call variants",
    )
    rate: Optional[StrictStr] = Field(
        default=None,
        description="Coupon rate amount (present for regular coupon payments)",
    )
    record_date: Optional[date] = Field(default=None, description="The record date")


