class OptionContract(ValidateBaseModel):
    """
    OptionContract
    """

    close_price: Optional[StrictStr] = Field(
        default=None,
        description="The close price of the option contract.",
        json_schema_extra={"examples": ["148.38"]},
    )
    close_price_date: Optional[date] = Field(
        default=None,
        description="The date of the close price data.",
        json_schema_extra={"examples": ["2023-12-11"]},
    )
    deliverables: Optional[List[OptionDeliverable]] = Field(
        default=None,
        description="Represents the deliverables tied to the option contract. While standard contracts entail a single deliverable, non-standard ones can encompass multiple deliverables, each potentially customized with distinct parameters. This array is included in the list contracts response only if the query parameter show_deliverables=true is provided. ",
    )
    expiration_date: date = Field(
        description="The expiration date of the option contract.",
        json_schema_extra={"examples": ["2025-06-20"]},
    )
    id: UUID = Field(
        description="The unique identifier of the option contract.",
        json_schema_extra={"examples": ["98359ef7-5124-49f3-85ea-5cf02df6defa"]},
    )
    multiplier: StrictStr = Field(
        description="The multiplier of the option contract is crucial for calculating both the trade premium and the extended strike price. In standard contracts, the multiplier is always set to 100. For instance, if a contract is traded at $1.50 and the multiplier is 100, the total amount debited when buying the contract would be $150.00. Similarly, when exercising a call contract, the total cost will be equal to the strike price times the multiplier.",
        json_schema_extra={"examples": ["100"]},
    )
    name: StrictStr = Field(
        description="The name of the option contract.",
        json_schema_extra={"examples": ["AAPL Jun 20 2025 100 Call"]},
    )
    open_interest: Optional[StrictStr] = Field(
        default=None,
        description="The open interest of the option contract.",
        json_schema_extra={"examples": ["237"]},
    )
    open_interest_date: Optional[date] = Field(
        default=None,
        description="The date of the open interest data.",
        json_schema_extra={"examples": ["2023-12-11"]},
    )
    ppind: StrictBool = Field(
        description="The ppind (Penny Program Indicator) field indicates whether an option contract is eligible for penny price increments, with `true` meaning it is part of the Penny Program and `false` meaning it is not.",
        json_schema_extra={"examples": [True]},
    )
    root_symbol: Optional[StrictStr] = Field(
        default=None,
        description="The root symbol of the option contract.",
        json_schema_extra={"examples": ["AAPL"]},
    )
    size: StrictStr = Field(
        description="Represents the number of underlying shares to be delivered in case the contract is exercised/assigned. For standard contracts, this is always 100. This field should **not** be used as a multiplier, specially for non-standard contracts.",
        json_schema_extra={"examples": ["100"]},
    )
    status: OptionContractStatus
    strike_price: StrictStr = Field(
        description="The strike price of the option contract.",
        json_schema_extra={"examples": ["100"]},
    )
    style: OptionContractStyle
    symbol: StrictStr = Field(
        description="The symbol representing the option contract.",
        json_schema_extra={"examples": ["AAPL250620C00100000"]},
    )
    tradable: StrictBool = Field(
        description="Indicates whether the option contract is tradable.",
        json_schema_extra={"examples": [True]},
    )
    type: OptionContractType
    underlying_asset_id: UUID = Field(
        description="The unique identifier of the underlying asset.",
        json_schema_extra={"examples": ["b0b6dd9d-8b9b-48a9-ba46-b9d54906e415"]},
    )
    underlying_symbol: StrictStr = Field(
        description="The underlying symbol of the option contract.",
        json_schema_extra={"examples": ["AAPL"]},
    )


