class Order(ModelWithID):
    """
    The Orders API allows a user to monitor, place and cancel their orders with Alpaca.

    Each order has a unique identifier provided by the client. This client-side unique order ID will be automatically generated by the system if not provided by the client, and will be returned as part of the order object along with the rest of the fields described below. Once an order is placed, it can be queried using the client-side order ID to check the status.

    Updates on open orders at Alpaca will also be sent over the streaming interface, which is the recommended method of maintaining order state.
    """

    asset_class: Optional[AssetClass] = None
    asset_id: Optional[UUID] = Field(
        default=None,
        description="Asset ID (For options this represents the option contract ID)",
    )
    canceled_at: Optional[datetime] = None
    client_order_id: Optional[Annotated[str, Field(strict=True, max_length=128)]] = (
        Field(default=None, description="Client unique order ID")
    )
    created_at: Optional[datetime] = None
    expired_at: Optional[datetime] = None
    expires_at: Optional[datetime] = None
    extended_hours: Optional[StrictBool] = Field(
        default=None,
        description="If true, eligible for execution outside regular trading hours.",
    )
    failed_at: Optional[datetime] = None
    filled_at: Optional[datetime] = None
    filled_avg_price: Optional[StrictStr] = Field(
        default=None, description="Filled average price"
    )
    filled_qty: Optional[Annotated[str, Field(min_length=1, strict=True)]] = Field(
        default=None, description="Filled quantity"
    )
    group_id: Optional[UUID] = Field(
        default=None,
        description="Opaque identifier shared by every order in the same `bracket`, `oto`, or `oco` order, including its legs and any replacement orders. Use it to associate related orders received from the `trade_updates` stream, where `legs` is not populated. Omitted for other orders.",
        json_schema_extra={"examples": ["3f1c2b7e-8d4a-4c6e-9f2a-5b7d1e0c9a84"]},
    )
    group_role: Optional[OrderGroupRole] = None
    hwm: Optional[StrictStr] = Field(
        default=None,
        description="The highest (lowest) market price seen since the trailing stop order was submitted.",
    )
    id: Optional[UUID] = Field(default=None, description="Order ID")
    legs: Optional[List[OrderLeg]] = Field(
        default=None,
        description="When querying non-simple order_class orders in a nested style, an array of Order entities associated with this order. Otherwise, null. Required if order class is `mleg`.",
    )
